import { useState, useEffect, useRef } from 'react';
import './Login.css';

const ADMIN_PW  = '170417';
const VIEWER_PW = 'pfcpfc1!';

export default function Login({ onLogin }) {
  const [pw, setPw]         = useState('');
  const [error, setError]   = useState('');
  const [ready, setReady]   = useState(false);
  const inputRef            = useRef(null);

  // Chrome 자동완성 차단: 처음 100ms 동안 readOnly 유지
  useEffect(() => {
    const t = setTimeout(() => {
      setReady(true);
      // readOnly 해제 후 포커스 + 혹시 남은 값 제거
      setPw('');
      inputRef.current?.focus();
    }, 100);
    return () => clearTimeout(t);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (pw === ADMIN_PW) {
      onLogin('admin');
    } else if (pw === VIEWER_PW) {
      onLogin('viewer');
    } else {
      setError('비밀번호가 올바르지 않습니다.');
      setPw('');
    }
  };

  return (
    <div className="login-wrap">
      <div className="login-card">
        <div className="login-logo">PF Chang's</div>
        <div className="login-title">브랜드 매출 분석 대시보드</div>
        <form onSubmit={handleSubmit} className="login-form" autoComplete="off">
          <input
            ref={inputRef}
            type="password"
            placeholder="비밀번호를 입력하세요"
            value={pw}
            readOnly={!ready}
            onChange={(e) => { setPw(e.target.value); setError(''); }}
            className="login-input"
            autoComplete="new-password"
          />
          {error && <div className="login-error">{error}</div>}
          <button type="submit" className="login-btn">로그인</button>
        </form>
        <div className="login-hint">본사 담당자 전용 시스템</div>
        <div style={{ fontSize: 10, color: '#d1d5db', marginTop: 8 }}>v2504e</div>
      </div>
    </div>
  );
}
