import { useMemo } from 'react';
import { formatKRW } from '../utils/calcMetrics';
import './AnomalyAlert.css';

export default function AnomalyAlert({ allData }) {
  const anomalies = useMemo(() => {
    if (allData.length === 0) return [];

    // 매장별로 원본 데이터 인덱싱 (store → year → month → record)
    const storeMap = {};
    allData.forEach((d) => {
      if (!storeMap[d.store]) storeMap[d.store] = {};
      if (!storeMap[d.store][d.year]) storeMap[d.store][d.year] = {};
      storeMap[d.store][d.year][d.month] = d;
    });

    // 데이터 전체에서 가장 최신 연월 파악
    const allKeys = allData.map((d) => `${d.year}-${String(d.month).padStart(2,'0')}`);
    const latestKey = allKeys.sort().reverse()[0];
    const [latestYear, latestMonthPad] = latestKey.split('-');
    const latestMonth = latestMonthPad; // '04' 형태

    // 진행 중인 달의 누적 일수 파악 (dailyTotals 기반)
    const getDayCount = (record) => {
      if (!record || !record.dailyTotals) return 0;
      return record.dailyTotals.filter((d) => d.sales > 0).length;
    };

    // 진행 중인 달의 N일치 매출 계산 (전년 동기간 비교용)
    const getSalesUpToDay = (record, dayCount) => {
      if (!record || !record.dailyTotals) return 0;
      const sorted = [...record.dailyTotals].sort((a, b) =>
        String(a.date).localeCompare(String(b.date))
      );
      return sorted.slice(0, dayCount).reduce((s, d) => s + (d.sales || 0), 0);
    };

    const alerts = [];

    Object.entries(storeMap).forEach(([store, yearMap]) => {
      const years = Object.keys(yearMap).sort();

      years.forEach((year) => {
        const months = Object.keys(yearMap[year]).sort();

        months.forEach((month) => {
          const curKey = `${year}-${String(month).padStart(2,'0')}`;
          const isLatestMonth = curKey === latestKey;

          const curRecord = yearMap[year][month];
          const curDayCount = getDayCount(curRecord);
          if (curDayCount === 0) return;

          // ── 1. 전년 동기간 대비 비교 ──────────────────────────
          // (완료월, 진행중월 모두 적용. 진행 중이면 같은 일수만큼만 비교)
          const prevYear = String(Number(year) - 1);
          const prevYearRecord = yearMap[prevYear]?.[month];

          if (prevYearRecord) {
            const prevDayCount = getDayCount(prevYearRecord);
            if (prevDayCount > 0) {
              // 진행 중인 달이면 전년 같은 일수만 비교, 완료된 달이면 전체 비교
              const compareDays = isLatestMonth ? curDayCount : Math.min(curDayCount, prevDayCount);
              const curSales = isLatestMonth
                ? getSalesUpToDay(curRecord, compareDays)
                : curRecord.totalSales;
              const prevSales = getSalesUpToDay(prevYearRecord, compareDays);

              if (prevSales > 0) {
                const yoyRate = ((curSales - prevSales) / prevSales) * 100;
                if (yoyRate < -10) {
                  const periodLabel = isLatestMonth
                    ? `(${compareDays}일 기준)`
                    : '';
                  alerts.push({
                    type: 'yoy',
                    store,
                    curKey,
                    prevKey: `${prevYear}-${String(month).padStart(2,'0')}`,
                    curSales,
                    prevSales,
                    decline: Math.abs(yoyRate),
                    periodLabel,
                  });
                }
              }
            }
          }

        });
      });
    });

    return alerts.sort((a, b) => b.decline - a.decline).slice(0, 5);
  }, [allData]);

  if (anomalies.length === 0) return null;

  return (
    <div className="anomaly-alerts">
      {anomalies.map((alert, idx) => (
        <div key={idx} className={`anomaly-alert alert-${alert.type}`}>
          <span className="alert-icon">⚠️</span>
          <span className="alert-text">
            {`${alert.store} ${alert.curKey}: 전년 동기 대비 ${alert.decline.toFixed(1)}% 하락 ${alert.periodLabel} (전년 ${formatKRW(alert.prevSales)}원 → 금년 ${formatKRW(alert.curSales)}원)`}
          </span>
        </div>
      ))}
    </div>
  );
}
