import { useState, useMemo, useEffect } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer, Cell
} from 'recharts';
import { formatKRW, formatShort, sortByStore, STORE_ORDER } from '../utils/calcMetrics';
import './BudgetActual.css';

const STORE_COLORS = ['#0d2258','#1d4ed8','#7c3aed','#0f766e','#dc2626','#d97706','#059669','#be185d'];

function storeColor(store) {
  const idx = STORE_ORDER.indexOf(store);
  return STORE_COLORS[idx !== -1 ? idx : 0];
}

const STORAGE_KEY = 'brand-budget-v1';

function loadBudgets() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  } catch {
    return {};
  }
}

function saveBudgets(budgets) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(budgets));
}

export default function BudgetActual({ allData, filters }) {
  const [budgets, setBudgets] = useState(loadBudgets());
  const [editingCell, setEditingCell] = useState(null);
  const [tempValue, setTempValue] = useState('');

  const stores = useMemo(() => {
    const all = [...new Set(allData.map((d) => d.store))];
    return all.sort((a, b) => STORE_ORDER.indexOf(a) - STORE_ORDER.indexOf(b));
  }, [allData]);

  const year = filters.year || new Date().getFullYear().toString();

  const getBudget = (y, store, month) => {
    return budgets?.[y]?.[store]?.[month] || 0;
  };

  // 월별 실적 계산
  const actualData = useMemo(() => {
    const monthMap = {};
    allData
      .filter((d) => !filters.year || d.year === filters.year)
      .forEach((d) => {
        const month = d.month;
        if (!monthMap[month]) {
          monthMap[month] = {};
        }
        if (!monthMap[month][d.store]) {
          monthMap[month][d.store] = 0;
        }
        monthMap[month][d.store] += d.totalSales || 0;
      });
    return monthMap;
  }, [allData, filters]);

  // 차트 데이터
  const chartData = useMemo(() => {
    const months = Array.from({ length: 12 }, (_, i) => i + 1);
    return months.map((m) => {
      const entry = {
        month: `${m}월`,
        monthNum: m,
      };
      stores.forEach((store) => {
        const budget = getBudget(year, store, m);
        const actual = actualData[m]?.[store] || 0;
        entry[`${store}_budget`] = budget;
        entry[`${store}_actual`] = actual;
      });
      return entry;
    });
  }, [year, stores, actualData]);

  const setBudget = (year, store, month, value) => {
    setBudgets((prev) => {
      const updated = JSON.parse(JSON.stringify(prev));
      if (!updated[year]) updated[year] = {};
      if (!updated[year][store]) updated[year][store] = {};
      updated[year][store][month] = parseInt(value) || 0;
      saveBudgets(updated);
      return updated;
    });
  };

  const handleCellDoubleClick = (year, store, month) => {
    const value = getBudget(year, store, month);
    setEditingCell({ year, store, month });
    setTempValue(value.toString());
  };

  const handleSave = () => {
    if (editingCell) {
      setBudget(editingCell.year, editingCell.store, editingCell.month, tempValue);
      setEditingCell(null);
      setTempValue('');
    }
  };

  const handleCancel = () => {
    setEditingCell(null);
    setTempValue('');
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') handleSave();
    if (e.key === 'Escape') handleCancel();
  };

  // 달성률 계산
  const achievements = useMemo(() => {
    const result = {};
    stores.forEach((store) => {
      result[store] = Array.from({ length: 12 }, (_, m) => {
        const budget = getBudget(year, store, m + 1);
        const actual = actualData[m + 1]?.[store] || 0;
        const rate = budget > 0 ? (actual / budget) * 100 : 0;
        return rate;
      });
    });
    return result;
  }, [year, stores, budgets, actualData]);

  if (allData.length === 0) {
    return <div className="daily-empty">파일을 먼저 업로드해주세요.</div>;
  }

  return (
    <div className="budget-actual">
      {/* 예산 입력 테이블 */}
      <div className="chart-card">
        <div className="chart-title">{year}년 매장별 월간 목표 (원)</div>
        <div style={{ overflowX: 'auto' }}>
          <table className="budget-table">
            <thead>
              <tr>
                <th>매장</th>
                {Array.from({ length: 12 }, (_, i) => (
                  <th key={i + 1}>{i + 1}월</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {stores.map((store) => (
                <tr key={store}>
                  <td className="td-store">{store}</td>
                  {Array.from({ length: 12 }, (_, m) => {
                    const month = m + 1;
                    const isEditing =
                      editingCell?.year === year &&
                      editingCell?.store === store &&
                      editingCell?.month === month;
                    return (
                      <td
                        key={`${store}-${month}`}
                        className="budget-cell"
                        onDoubleClick={() => handleCellDoubleClick(year, store, month)}
                      >
                        {isEditing ? (
                          <div className="edit-cell">
                            <input
                              autoFocus
                              type="number"
                              value={tempValue}
                              onChange={(e) => setTempValue(e.target.value)}
                              onKeyDown={handleKeyDown}
                              onBlur={handleSave}
                              onClick={(e) => e.stopPropagation()}
                            />
                          </div>
                        ) : (
                          formatKRW(getBudget(year, store, month)) + '원'
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="budget-hint">더블클릭으로 목표를 입력하세요. 입력 후 자동 저장됩니다.</div>
      </div>

      {/* 예산 vs 실적 비교 */}
      <div className="chart-card">
        <div className="chart-title">예산 vs 실적 비교</div>
        <ResponsiveContainer width="100%" height={350}>
          <BarChart data={chartData} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="month" tick={{ fontSize: 11 }} />
            <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
            <Tooltip
              formatter={(v, name) => {
                const prefix = name.includes('budget') ? '목표' : '실적';
                return [`${formatKRW(v)}원`, prefix];
              }}
            />
            <Legend />
            {stores.map((store, idx) => (
              <Bar
                key={`${store}-budget`}
                dataKey={`${store}_budget`}
                fill={STORE_COLORS[idx % STORE_COLORS.length]}
                opacity={0.6}
                name={`${store} 목표`}
              />
            ))}
            {stores.map((store, idx) => (
              <Bar
                key={`${store}-actual`}
                dataKey={`${store}_actual`}
                fill={STORE_COLORS[idx % STORE_COLORS.length]}
                opacity={1}
                name={`${store} 실적`}
              />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* 달성률 테이블 */}
      <div className="chart-card">
        <div className="chart-title">월별 달성률 (%)</div>
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>매장</th>
                {Array.from({ length: 12 }, (_, i) => (
                  <th key={i + 1}>{i + 1}월</th>
                ))}
                <th>연간 평균</th>
              </tr>
            </thead>
            <tbody>
              {stores.map((store) => {
                const rates = achievements[store] || [];
                const avgRate = rates.length > 0 ? rates.reduce((a, b) => a + b) / rates.length : 0;
                return (
                  <tr key={store}>
                    <td className="td-store">{store}</td>
                    {rates.map((rate, m) => (
                      <td key={m} className="td-num" style={{ color: getAchievementColor(rate) }}>
                        {rate.toFixed(1)}%
                      </td>
                    ))}
                    <td className="td-num" style={{ fontWeight: 600, color: getAchievementColor(avgRate) }}>
                      {avgRate.toFixed(1)}%
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function getAchievementColor(rate) {
  if (rate >= 100) return '#16a34a';
  if (rate >= 90) return '#0d2258';
  if (rate >= 80) return '#f59e0b';
  return '#dc2626';
}
